{
  "active": true,
  "entityName": "Lead",
  "fieldName": "Status",
  "masterLabel": "Default",
  "pathAssistantSteps": [
    {
      "fieldNames": [
        "Company",
        "Website",
        "Industry",
        "NumberOfEmployees"
      ],
      "info": "<p><b style=\"font-family: Arial; font-size: 10pt;\">Determine which leads are qualified or unqualified.</b></p><ul><li><span style=\"font-size: 10pt;\">Assign the lead to a representative</span></li><li><span style=\"font-size: 10pt;\">Gather key details on the lead from their company&#39;s website</span></li><li><span style=\"font-size: 10pt;\">Create a plan to build a connection with this lead</span></li></ul>",
      "picklistValueName": "New"
    },
    {
      "fieldNames": [
        "Rating"
      ],
      "info": "<p><b style=\"font-family: Arial; font-size: 10pt;\">Nurture your leads and identify opportunities.</b></p><ul><li><span style=\"font-size: 10pt;\">Identify pain points that you can solve for this lead</span></li><li><span style=\"font-size: 10pt;\">Determine the likelihood of this lead converting</span></li><li><span style=\"font-size: 10pt;\">If this lead is qualified, convert it to an opportunity</span></li><li><span style=\"font-size: 10pt;\">Ensure that Marketing and Sales work together to develop your lead qualifying process</span></li></ul>",
      "picklistValueName": "Nurturing"
    },
    {
      "fieldNames": [],
      "info": "<p><b style=\"font-family: Arial; font-size: 10pt;\">Hooray! You have a new deal to bring across the finish line.</b></p>",
      "picklistValueName": "Qualified"
    },
    {
      "fieldNames": [
        "LeadSource"
      ],
      "info": "<p><b style=\"font-family: Arial; font-size: 10pt;\">Keep track of the info related to your unqualified leads.</b></p><p><span style=\"font-family: Arial; font-size: 10pt;\">Your lead may be unqualified if they are not interested in your products or they have left the company associated with the prospect.</span></p><ul><li><span style=\"font-size: 10pt;\">Document lessons learned for future reference</span></li><li><span style=\"font-size: 10pt;\">Save outreach details and contact information</span></li></ul>",
      "picklistValueName": "Unqualified"
    },
    {
      "fieldNames": [
        "Title",
        "Email",
        "Phone"
      ],
      "info": "<p><b style=\"font-family: Arial; font-size: 10pt;\">Qualify promising leads.</b></p><ul><li><span style=\"font-size: 10pt;\">Identify a contact for the lead</span></li><li><span style=\"font-size: 10pt;\">Save their contact information to the lead record</span></li><li><span style=\"font-size: 10pt;\">Make a plan for your outreach (For example, How many times will you reach out? What&#39;s your pitch?)</span></li></ul>",
      "picklistValueName": "Working"
    }
  ],
  "recordTypeName": "__MASTER__",
  "urls": null
}
